#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> part1, part2;
    int max_mod = 0;

    int half = (n / 2) + (n % 2);
    int half2 = n / 2;

    // Generate all subset sums for the first half
    for (int subset_mask = 0; subset_mask < (1 << half); ++subset_mask) {
        int sum_value = 0;
        int current_mask = subset_mask;
        for (int _ = 0; _ < 20; ++_) {
            if (current_mask & 1) {
                sum_value += a[_];
            }
            current_mask >>= 1;
        }
        part1.push_back(sum_value % m);
    }
    std::sort(part1.begin(), part1.end());

    // Generate all subset sums for the second half
    for (int subset_mask = 0; subset_mask < (1 << half2); ++subset_mask) {
        int sum_value = 0;
        int current_mask = subset_mask;
        for (int _ = 0; _ < 20; ++_) {
            if (current_mask & 1) {
                sum_value += a[half + (n % 2) + _];
            }
            current_mask >>= 1;
        }
        sum_value %= m;

        int target = m - sum_value - 1;
        auto it = std::lower_bound(part1.begin(), part1.end(), target);
        int candidate;
        if (it != part1.end()) {
            candidate = *it;
            if (candidate > target && it != part1.begin()) {
                candidate = *(it - 1);
            }
        } else {
            candidate = part1.back();
        }
        max_mod = max(max_mod, (sum_value + candidate) % m);
        max_mod = max(max_mod, (sum_value + part1.back()) % m);
    }

    cout << max_mod << "\n";

    return 0;
}
